mapper.select:
select user_id, algorithm, samples, status, create_time, update_time
from sys_user_face
where user_id = #{userId}

mapper.update:
update sys_user_face
set descriptor = #{encrypted}
where user_id = #{userId} and binary descriptor = binary #{previous}

mapper.insert:
insert into sys_user_face_policy (user_id, enabled)
select user_id, #{enabled}
from sys_user
where user_id = #{userId} and del_flag = '0'
on duplicate key update enabled = #{enabled}

mapper.update:
update sys_user_face
descriptor = #{descriptor}, algorithm = #{algorithm}, samples = #{samples}, quality = #{quality}, status = #{status}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark}, consent_at = #{consentAt}, consent_version = #{consentVersion},
where user_id = #{userId}
